# Surah Al-Kahf (chapter 18) — part 5: ayat 41-50 (IDs 2181-2190)
SURAH = 18

ENTRIES = {
2181: (
"یا اس کا پانی زمین میں جذب ہو جائے پس تو اسے کبھی نہیں پا سکے گا",
"""۱۔ یا اللہ باغ کا پانی خشک کر دے؛ پھر مالدار کو کوئی سہولت نہیں۔
۲۔ ’’أَوْ يُصْبِحَ مَاؤُهَا غَوْرًا فَلَن تَسْتَطِيعَ لَهُ طَلَبًا‘‘ — یا اس کا پانی زمین میں جذب ہو جائے پس تو اسے کبھی نہیں پا سکے گا — یعنی یا اس کا پانی زمین میں جذب ہو جائے پس تو اسے ڈھونڈ بھی نہیں سکے گا۔
۳۔ عملی سبق: اللہ کی نعمتیں ٹیسٹ ہیں؛ غرور نہ کرو؛ اللہ کی پناہ مانگو۔"""
),
2182: (
"اور اس کا پھل برباد ہو گیا پس وہ اپنی دونوں ہاتھ ملنے لگا اور اپنے کہنے پر پچھتایا کہ میں اپنے رب کے ساتھ کسی کو شریک کیوں ٹھہرایا تھا جبکہ وہ ویرانہ اور کھنڈر ہے",
"""۱۔ اللہ نے مالدار شخص کی نادانی کا انجام دکھایا؛ باغ برباد؛ ہاتھ ملنے لگا؛ شرک پر افسوس۔
۲۔ ’’وَأُحِيطَ بِثَمَرِهِ فَأَصْبَحَ يُقَلِّبُ كَفَّيْهِ عَلَىٰ مَا أَنفَقَ فِيهَا وَهِيَ خَاوِيَۃٌ عَلَىٰ عُرُوشِهَا وَيَقُولُ يَا لَيْتَنِي لَمْ أُشْرِكْ بِرَبِّي أَحَدًا‘‘ — اور اس کا پھل برباد ہو گیا پس وہ اپنی دونوں ہاتھ ملنے لگا اور اپنے کہنے پر پچھتایا کہ میں اپنے رب کے ساتھ کسی کو شریک کیوں ٹھہرایا تھا جبکہ وہ ویرانہ اور کھنڈر ہے — یعنی اس کی فصل برباد ہو گئی پس وہ اپنے عمل پر ہاتھ ملتا رہا جبکہ باغ کی عمارت گری ہوئی تھی اور کہنے لگا کہ کاش میں اپنے رب کے ساتھ کسی کو شریک نہ ٹھہراتا۔
۳۔ عملی سبق: دنیا کی فانی دولت پر غرور نہ کرو؛ اللہ پر بھروسہ کرو؛ شرک سے بچو۔"""
),
2183: (
"اور اس کا کوئی گروہ نہ تھا جو اس کے سوا اللہ سے اس کی مدد کرتا — اور وہ خود بھی مدد کرنے کی طاقت نہ رکھتا تھا",
"""۱۔ مالدار شخص اکیلا تھا؛ نہ کوئی مددگار نہ کوئی طاقت؛ دنیا کی دولت بے کار ہو گئی۔
۲۔ ’’وَلَمْ تَكُن لَّهُ فِئَۃٌ يَنصُرُونَهُ مِن دُونِ اللَّهِ وَمَا كَانَ مُنتَصِرًا‘‘ — اور اس کا کوئی گروہ نہ تھا جو اس کے سوا اللہ سے اس کی مدد کرتا — اور وہ خود بھی مدد کرنے کی طاقت نہ رکھتا تھا — یعنی اس کا کوئی گروہ نہ تھا جو اللہ کے سوا اس کی مدد کرے اور وہ خود بھی بچ نہ سکا۔
۳۔ عملی سبق: دنیا کی طاقت اللہ کے مقابلے میں کچھ نہیں؛ اللہ پر بھروسہ کرو۔"""
),
2184: (
"یہاں اصل فرماں روائی اللہ کی ہے جو حق ہے — وہ بہترین ثواب دینے والا اور بہترین نتیجہ ہے",
"""۱۔ ہر غلبہ بالآخر اللہ کا ہے؛ موت کے بعد صرف اللہ کا نظام قائل ہے۔
۲۔ ’’هُنَالِكَ الْوَلَاۃُ لِلَّهِ الْحَقِّ هُوَ خَيْرٌ ثَوَابًا وَخَيْرٌ عُقْبًا‘‘ — یہاں اصل فرماں روائی اللہ کی ہے جو حق ہے — وہ بہترین ثواب دینے والا اور بہترین نتیجہ ہے — یعنی اس وقت وہاں صرف اللہ کی فرماں روائی ہوگی جو حق ہے — وہی بہترین ثواب دینے والا اور بہترین انجام والا ہے۔
۳۔ عملی سبق: اللہ کی حکومت سچی ہے؛ اس پر ایمان لاؤ؛ اس کے فیصلے پر خوش رہو۔"""
),
2185: (
"اور ان کے لیے دنیا کی زندگی کی مثال بیان کرو جیسے پانی جس کو ہم آسمان سے نازل کرتے ہیں پھر اس سے زمین کی روئیدگی گھنی ہو جاتی ہے — پھر وہ خشک ہو جاتی ہے اور ہوائیں اسے اڑا لے جاتی ہیں — اور اللہ ہر چیز پر قدرت رکھنے والا ہے",
"""۱۔ دنیا کی زندگی پانی کی طرح — ایک لمحے ہری پھر خشک؛ اللہ ہر چیز پر قادر ہے۔
۲۔ ’’وَاضْرِبْ لَهُم مَّثَلَ الْحَيَاۃِ الدُّنْيَا كَمَاءٍ أَنزَلْنَاهُ مِنَ السَّمَاءِ فَاخْتَلَطَ بِهِ نَبَاتُ الْأَرْضِ فَأَصْبَحَ هَشِيمًا تَذْرُوهُ الرِّيَاحُ وَكَانَ اللَّهُ عَلَىٰ كُلِّ شَيْءٍ مُّقْتَدِرًا‘‘ — اور ان کے لیے دنیا کی زندگی کی مثال بیان کرو جیسے پانی جس کو ہم آسمان سے نازل کرتے ہیں پھر اس سے زمین کی روئیدگی گھنی ہو جاتی ہے — پھر وہ خشک ہو جاتی ہے اور ہوائیں اسے اڑا لے جاتی ہیں — اور اللہ ہر چیز پر قدرت رکھنے والا ہے — یعنی آپ ان کے لیے دنیا کی زندگی کی مثال بیان کریں جیسے پانی جو ہم آسمان سے اتارتے ہیں اس سے زمین کی پیداوار اگتی ہے پھر وہ خشک ہو جاتی ہے اور ہوائیں اسے اڑا لے جاتی ہیں اور اللہ ہر چیز پر قدرت رکھنے والا ہے۔
۳۔ عملی سبق: دنیا کا فتنہ زہریلا ہے؛ دائمی چیز آخرت ہی ہے؛ نیک عمل کرو۔"""
),
2186: (
"مال اور اولاد دنیا کی زندگی کی زینت ہے — اور باقی رہنے والی نیکیاں آپ کے رب کے نزدیک ثواب اور امید کے اعتبار سے بہتر ہیں",
"""۱۔ مال و اولاد زینت ہیں؛ مگر باقی نیکیاں اللہ کے ہاں زیادہ بہتر ہیں۔
۲۔ ’’الْمَالُ وَالْبَنُونَ زِينَۃُ الْحَيَاۃِ الدُّنْيَا وَالْبَاقِيَاتُ الصَّالِحَاتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًا وَخَيْرٌ أَمَلًا‘‘ — مال اور اولاد دنیا کی زندگی کی زینت ہے — اور باقی رہنے والی نیکیاں آپ کے رب کے نزدیک ثواب اور امید کے اعتبار سے بہتر ہیں — یعنی مال اور اولاد دنیا کی زندگی کی زینت ہیں مگر باقی نیکیاں آپ کے رب کے نزدیک ثواب اور امید کے اعتبار سے بہتر ہیں۔
۳۔ عملی سبق: باقی نیکیاں اختیار کرو؛ مال کو آخرت کے لیے استعمال کرو۔"""
),
2187: (
"اور جس دن ہم پہاڑوں کو چلائیں گے اور تم زمین کو کھلا میدان دیکھو گے — اور ہم انہیں اکٹھا کریں گے اور ان میں سے کسی کو چھوڑیں گے نہیں",
"""۱۔ قیامت کا منظر — پہاڑ اڑتے؛ زمین کھلی؛ سب اکٹھے؛ کوئی نہ بھاگ سکے گا۔
۲۔ ’’وَيَوْمَ نُسَيِّرُ الْجِبَالَ وَتَرَى الْأَرْضَ بَارِزَۃً وَحَشَرْنَاهُمْ فَلَمْ نُغَادِرْ مِنْهُمْ أَحَدًا‘‘ — اور جس دن ہم پہاڑوں کو چلائیں گے اور تم زمین کو کھلا میدان دیکھو گے — اور ہم انہیں اکٹھا کریں گے اور ان میں سے کسی کو چھوڑیں گے نہیں — یعنی جس دن ہم پہاڑوں کو چلائیں گے اور تو زمین کو کھلا میدان دیکھے گا اور ہم ان سب کو اکٹھا کریں گے اور ان میں سے کسی کو نہ چھوڑیں گے۔
۳۔ عملی سبق: قیامت کی تیاری کرو؛ دنیا کی زندگی حساب کتاب ہے۔"""
),
2188: (
"اور وہ آپ کے رب کے سامنے صف میں پیش کیے جائیں گے — یقیناً تم ہمارے پاس اسی حالت میں آئے ہو جس طرح ہم نے تمہیں پہلی بار بنایا تھا — بلکہ تم نے خیال کیا تھا کہ ہم تمہارے لیے کوئی مقررہ وقت نہیں رکھیں گے",
"""۱۔ قیامت میں سب صفِ بستہ حاضر ہوں گے؛ اللہ یاد دلائے گا: ہم نے پہلے بھی تمہیں بنایا تھا؛ تم نے قیامت کا انکار کیا تھا۔
۲۔ ’’وَعُرِضُوا عَلَىٰ رَبِّكَ صَفًّا لَّقَدْ جِئْتُمُونَا كَمَا خَلَقْنَاكُمْ أَوَّلَ مَرَّۃٍ بَلْ زَعَمْتُمْ أَلَّن نَّجْعَلَ لَكُم مَّوْعِدًا‘‘ — اور وہ آپ کے رب کے سامنے صف میں پیش کیے جائیں گے — یقیناً تم ہمارے پاس اسی حالت میں آئے ہو جس طرح ہم نے تمہیں پہلی بار بنایا تھا — بلکہ تم نے خیال کیا تھا کہ ہم تمہارے لیے کوئی مقررہ وقت نہیں رکھیں گے — یعنی انہیں آپ کے رب کے سامنے صف میں پیش کیا جائے گا — یقیناً تم اسی حالت میں ہمارے پاس آئے جیسی پہلی بار تخلیق ہوئے تھے بلکہ تم نے خیال کیا تھا کہ ہم تمہارے لیے کوئی مقررہ وقت نہیں رکھیں گے۔
۳۔ عملی سبق: قیامت پر یقین رکھو؛ وہاں کی جواب دہی سے بچنے کے لیے نیک عمل کرو۔"""
),
2189: (
"اور کتاب رکھی جائے گی — پس آپ مجرموں کو اس کے عذاب سے خوفزدہ دیکھیں گے اور کہیں گے ہائے ہماری ہلاکت! یہ کیسی کتاب ہے جو چھوٹی اور بڑی کوئی چیز نہیں چھوڑتی سوائے اس کے کہ اسے شمار کر لیتی ہے — اور انہوں نے وہ سب جو کیا تیار پایا — اور آپ کا رب کسی پر ظلم نہیں کرتا",
"""۱۔ اعمالنامہ پیش ہوگا؛ مجرم لرز جائیں گے؛ ہر عمل لکھا ہوا؛ اللہ کوئی ظلم نہیں کرتا۔
۲۔ ’’وَوُضِعَ الْكِتَابُ فَتَرَى الْمُجْرِمِينَ مُشْفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَا وَيْلَتَنَا مَالِ هَٰذَا الْكِتَابِ لَا يُغَادِرُ صَغِيرَۃً وَلَا كَبِيرَۃً إِلَّا أَحْصَاهَا وَوَجَدُوا مَا عَمِلُوا حَاضِرًا وَلَا يَظْلِمُ رَبُّكَ أَحَدًا‘‘ — اور کتاب رکھی جائے گی — پس آپ مجرموں کو اس کے عذاب سے خوفزدہ دیکھیں گے اور کہیں گے ہائے ہماری ہلاکت! یہ کیسی کتاب ہے جو چھوٹی اور بڑی کوئی چیز نہیں چھوڑتی سوائے اس کے کہ اسے شمار کر لیتی ہے — اور انہوں نے وہ سب جو کیا تیار پایا — اور آپ کا رب کسی پر ظلم نہیں کرتا — یعنی اعمال کی کتاب رکھ دی جائے گی پس آپ مجرموں کو خوفزدہ دیکھیں گے اور وہ کہیں گے ہائے ہماری ہلاکت! یہ کیا کتاب ہے جو چھوٹی بڑی کوئی چیز نہیں چھوڑتی، سب کو شمار کر لیتی ہے — اور انہوں نے اپنے اعمال تیار پائے — اور آپ کا رب کسی پر ظلم نہیں کرتا۔
۳۔ عملی سبق: اپنا اعمالنامہ درست کرو؛ ہر عمل لکھا جاتا ہے؛ اللہ انصاف کرے گا۔"""
),
2190: (
"اور جب ہم نے فرشتوں سے کہا کہ آدم کو سجدہ کرو — پس سب سجدہ کیا سوائے ابلیس کے — وہ جنوں میں سے تھا اور اس نے اپنے رب کے حکم سے نافرمانی کی — کیا تم اسے اور اس کی اولاد کو میری جگہ حمایتی بناتے ہو؟ حالانکہ وہ تمہارے دشمن ہیں — ظالموں کے لیے کتنا برا بدلہ ہے",
"""۱۔ ابلیس کا تکبر — جنات میں سے تھا؛ آدمؑ کے سامنے سجدہ سے انکار؛ شیطان انسان کا دشمن ہے۔
۲۔ ’’وَإِذْ قُلْنَا لِلْمَلَائِكَۃِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ كَانَ مِنَ الْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِ أَفَتَتَّخِذُونَهُ وَذُرِّيَّتَهُ أَوْلِيَاءَ مِن دُونِي وَهُمْ لَكُمْ عَدُوٌّ بِئْسَ لِلظَّالِمِينَ بَدَلًا‘‘ — اور جب ہم نے فرشتوں سے کہا کہ آدم کو سجدہ کرو — پس سب سجدہ کیا سوائے ابلیس کے — وہ جنوں میں سے تھا اور اس نے اپنے رب کے حکم سے نافرمانی کی — کیا تم اسے اور اس کی اولاد کو میری جگہ حمایتی بناتے ہو؟ حالانکہ وہ تمہارے دشمن ہیں — ظالموں کے لیے کتنا برا بدلہ ہے — یعنی جب ہم نے فرشتوں سے کہا آدم کو سجدہ کرو تو سب نے سجدہ کیا سوائے ابلیس کے — وہ جنوں میں سے تھا اور اس نے اپنے رب کے حکم کی نافرمانی کی — کیا تم اسے اور اس کی ذریت کو میرے سوا کارساز بناتے ہو حالانکہ وہ تمہارے دشمن ہیں — ظالموں کے لیے بہت برا بدلہ ہے۔
۳۔ عملی سبق: شیطان اور اس کی اولاد انسان کے دشمن ہیں؛ ان کی پیروی نہ کرو؛ حق پر رہو۔"""
),
}
